svg.script:
    (function () {
      const allPaths = Array.from(document.querySelectorAll('.draw-path'));
      const svgRoot = document.querySelector('svg');
      const lacre = document.getElementById('lacre');

      const SPEED = 900;
      const MIN_DUR = 300;
      const MAX_DUR = 1200;
      const FILL_DUR = 250;
      const OVERLAP = 0.4;

	  // irregularity: 0 = círculo perfecto, 0.03 = sutil (como lo tenías), 
	  // 0.08+ = más orgánico/irregular
	  function buildWaxPath(cx, cy, r, irregularity = 0.03, N = 16) {
	    // patrón fijo de variación (-1 a 1) que se repite cada 10 puntos
	    const baseVariation = [0, 0.9, -0.6, 0.7, -0.9, 0.8, -0.3, 0.6, -0.7, 0.4];

	    const pts = [];
	    for (let i = 0; i < N; i++) {
	  	  const angle = (i / N) * Math.PI * 2;
	  	  const rad = r * (1 + irregularity * baseVariation[i % baseVariation.length]);
	  	  pts.push({
	  	    x: cx + Math.cos(angle) * rad,
	  	    y: cy + Math.sin(angle) * rad,
	  	    angle: angle
	  	  });
	    }

	    // longitud de tangente para aproximar un arco circular con N segmentos
	    const segAngle = (Math.PI * 2) / N;
	    const k = (4 / 3) * Math.tan(segAngle / 4);

	    let d = '';
	    for (let i = 0; i < N; i++) {
	  	  const p1 = pts[i];
	  	  const p2 = pts[(i + 1) % N];

	  	  // dirección tangente en cada punto (perpendicular al radio, sentido antihorario)
	  	  const t1x = -Math.sin(p1.angle), t1y = Math.cos(p1.angle);
	  	  const t2x = -Math.sin(p2.angle), t2y = Math.cos(p2.angle);

	  	  // el radio local de cada punto marca la longitud de su tangente
	  	  const r1 = Math.hypot(p1.x - cx, p1.y - cy);
	  	  const r2 = Math.hypot(p2.x - cx, p2.y - cy);

	  	  const c1x = p1.x + t1x * r1 * k;
	  	  const c1y = p1.y + t1y * r1 * k;
	  	  const c2x = p2.x - t2x * r2 * k;
	  	  const c2y = p2.y - t2y * r2 * k;

	  	  if (i === 0) d += `M ${p1.x.toFixed(2)},${p1.y.toFixed(2)} `;
	  	  d += `C ${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${p2.x.toFixed(2)},${p2.y.toFixed(2)} `;
	    }
	    return d + 'Z';
	  }

      const LACRE_IRREGULARITY = 0; // pon 0 para círculo perfecto, o 0.02-0.05 para un toque orgánico

	  function fitLacre() {
	    const logoPaths = allPaths.filter(p => p !== lacre);
	    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

	    logoPaths.forEach(p => {
	  	  const b = p.getBBox();
	  	  minX = Math.min(minX, b.x);
	  	  minY = Math.min(minY, b.y);
	  	  maxX = Math.max(maxX, b.x + b.width);
	  	  maxY = Math.max(maxY, b.y + b.height);
	    });

	    const cx = (minX + maxX) / 2;
	    const cy = (minY + maxY) / 2;
	    const halfDiag = Math.hypot(maxX - minX, maxY - minY) / 2;
	    const r = halfDiag * 1.15;

	    lacre.setAttribute('d', buildWaxPath(cx, cy, r, LACRE_IRREGULARITY));
	  }

      fitLacre();

      // --- medir y preparar todos los elementos (incluido el lacre) ---
      const lens = new Map();
      const durs = new Map();
      allPaths.forEach(p => {
        const len = p.getTotalLength();
        const dur = Math.max(MIN_DUR, Math.min(MAX_DUR, (len / SPEED) * 1000));
        lens.set(p, len);
        durs.set(p, dur);
        p.style.strokeDasharray = len;
        p.style.strokeDashoffset = len;
        p.style.fillOpacity = 0;
      });

      // --- agrupar por data-order ---
      const groupsMap = new Map();
      allPaths.forEach(p => {
        const order = +p.dataset.order;
        if (!groupsMap.has(order)) groupsMap.set(order, []);
        groupsMap.get(order).push(p);
      });
      const orders = Array.from(groupsMap.keys()).sort((a, b) => a - b);
      const groups = orders.map(order => groupsMap.get(order));

      // --- DIBUJAR ---
      function runElementForward(p) {
        const len = lens.get(p);
        const dur = durs.get(p);

        const strokeAnim = p.animate(
          [{ strokeDashoffset: len }, { strokeDashoffset: 0 }],
          { duration: dur, easing: 'ease-in-out', fill: 'forwards' }
        );

        return strokeAnim.finished.then(() => {
          const fillAnim = p.animate(
            [{ fillOpacity: 0 }, { fillOpacity: 1 }],
            { duration: FILL_DUR, easing: 'ease-out', fill: 'forwards' }
          );
          return fillAnim.finished;
        });
      }

      function playForward(onComplete) {
        allPaths.forEach(p => {
          p.style.strokeDashoffset = lens.get(p);
          p.style.fillOpacity = 0;
        });

        const allFinished = [];
        let t = 0;

        groups.forEach(group => {
          const start = t;
          group.forEach(p => {
            const finished = new Promise(resolve => {
              setTimeout(() => {
                runElementForward(p).then(resolve);
              }, start);
            });
            allFinished.push(finished);
          });
          const maxDur = Math.max(...group.map(p => durs.get(p)));
          t += (maxDur + FILL_DUR) * (1 - OVERLAP);
        });

        Promise.all(allFinished).then(() => {
          if (typeof onComplete === 'function') onComplete();
        });
      }

      // --- BORRAR ---
      function runElementReverse(p) {
        const len = lens.get(p);
        const dur = durs.get(p);

        const fillAnim = p.animate(
          [{ fillOpacity: 1 }, { fillOpacity: 0 }],
          { duration: FILL_DUR, easing: 'ease-in', fill: 'forwards' }
        );

        return fillAnim.finished.then(() => {
          const strokeAnim = p.animate(
            [{ strokeDashoffset: 0 }, { strokeDashoffset: len }],
            { duration: dur, easing: 'ease-in-out', fill: 'forwards' }
          );
          return strokeAnim.finished;
        });
      }

      function playReverse(onComplete) {
        const reversedGroups = [...groups].reverse();
        const allFinished = [];
        let t = 0;

        reversedGroups.forEach(group => {
          const start = t;
          group.forEach(p => {
            const finished = new Promise(resolve => {
              setTimeout(() => {
                runElementReverse(p).then(resolve);
              }, start);
            });
            allFinished.push(finished);
          });
          const maxDur = Math.max(...group.map(p => durs.get(p)));
          t += (FILL_DUR + maxDur) * (1 - OVERLAP);
        });

        Promise.all(allFinished).then(() => {
          if (typeof onComplete === 'function') onComplete();
        });
      }

      // --- orquestación: dibujar al cargar, borrar al clic ---
      let state = 'idle'; // idle -> ready -> erasing -> done

      svgRoot.addEventListener('click', () => {
        if (state !== 'ready') return;
        state = 'erasing';
        svgRoot.classList.remove('ready');

        playReverse(() => {
          state = 'done';
          svgRoot.dispatchEvent(new CustomEvent('sello-erased', { bubbles: true }));
        });
      });

      function start() {
        playForward(() => {
          state = 'ready';
          svgRoot.classList.add('ready');
        });
      }

      if (document.readyState === 'complete' || document.readyState === 'interactive') {
        start();
      } else {
        window.addEventListener('DOMContentLoaded', start);
      }
    })();
